export function treatmentOf(photo){return structuredClone({settings:photo.settings,intensity:photo.intensity,recipe:photo.recipe});}
export function inferAction(before,after){if(!before)return 'import';if(before.recipe?.id!==after.recipe?.id)return 'recipe';return 'adjust';}
export function stateChanges(before,after){const result=[];if(before?.recipe?.name!==after?.recipe?.name)result.push({label:'Receta',before:before?.recipe?.name||'Original',after:after?.recipe?.name||'Original'});if(before?.intensity!==after?.intensity)result.push({label:'Intensidad',before:before?.intensity??100,after:after?.intensity??100});const labels={laboratory:'Laboratorio',exposure:'Exposición',contrast:'Contraste',highlights:'Altas luces',shadows:'Sombras',whites:'Blancos',blacks:'Negros',temperature:'Temperatura',tint:'Matiz',saturation:'Saturación',vibrance:'Intensidad del color',fade:'Negros lavados',gamma:'Medios tonos',grain:'Grano',grainSize:'Tamaño del grano',sharpness:'Nitidez',clarity:'Claridad',denoise:'Suavizado de ruido',vignette:'Viñeta',colorChrome:'Profundidad del color',blueChrome:'Profundidad de azules',mono:'Blanco y negro',curve:'Curva de tonos',curvePoints:'Puntos de curva',hsl:'Mezclador HSL'};for(const key of Object.keys(after?.settings||{})){const a=before?.settings?.[key],b=after.settings[key];if(JSON.stringify(a)===JSON.stringify(b)||key==='laboratory'&&a==null&&b==null)continue;if(key==='curve'&&after.settings.curvePoints)continue;result.push({label:labels[key]||key,before:typeof a==='object'?describeSetting(key,a,before?.settings):a??'—',after:typeof b==='object'?describeSetting(key,b,after?.settings):b});}return result;}
export function safeRecipe(recipe){if(!recipe||typeof recipe!=='object'||!recipe.id||!recipe.name||!recipe.settings)return null;const out=structuredClone(recipe);out.name=String(out.name).slice(0,90);return out;}
export function guestKeys(uid){return {recipes:uid?'film-lab-recipes:'+uid:'film-lab-recipes',favorites:uid?'film-lab-favorites:'+uid:'film-lab-favorites'};}
export function nextCursor(items){const last=items.at(-1);return last?{date:last.created_at,id:last.id}:null;}

function describeSetting(key,value,settings){if(key==='laboratory'){if(!value)return 'Sin efectos';const f=value.film,g=value.grade,parts=[];if(f?.enabled)parts.push('Película: deslavado '+f.fade+', grano '+f.grain+', polvo '+f.dust+', fuga '+f.leak+' · temperatura '+(f.leakTemperature??100)+' ('+Math.round(f.leakX*100)+'%, '+Math.round(f.leakY*100)+'%) · textura '+value.seed);if(g?.enabled)parts.push('Color: sombras '+g.shadows+' / '+g.shadowAmount+', medios '+g.mids+' / '+g.midAmount+', luces '+g.highlights+' / '+g.highlightAmount);return parts.join(' · ')||'Efectos desactivados';}if(key==='curvePoints'){const points=value||settings?.curve?.map((y,i)=>({x:i/4,y}))||[];return points.map(p=>Math.round(p.x*100)+' → '+Math.round(p.y*100)).join(' · ');}if(key==='curve')return (value||[]).map(v=>Math.round(v*100)).join(' · ');if(key==='hsl'){const colors=['Rojo','Naranja','Amarillo','Verde','Cian','Azul','Violeta','Magenta'];return (value||[]).map((v,i)=>colors[i]+': tono '+v.h+', saturación '+v.s+', luz '+v.l).join('; ');}return 'Sin valores';}
